import { Entity, PrimaryGeneratedColumn, Column, OneToMany } from 'typeorm';
import { Banda } from '../../bandas/entities/banda.entity';

@Entity()
export class Genero {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ unique: true })
  nombre: string;

  @OneToMany(() => Banda, (banda) => banda.genero)
  bandas: Banda[];
}

import { Entity, PrimaryGeneratedColumn, Column, ManyToOne, JoinColumn } from 'typeorm';
import { Genero } from '../../generos/entities/genero.entity';

@Entity()
export class Banda {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  nombre: string;

  @Column()
  pais: string;

  @Column({ name: 'anio_formacion' })
  anioFormacion: number;

  @Column({ name: 'genero_id' })
  generoId: number;

  @ManyToOne(() => Genero, (genero) => genero.bandas)
  @JoinColumn({ name: 'genero_id' })
  genero: Genero;
}

import { IsString, IsNotEmpty, MaxLength, IsNumber, Min, Max } from 'class-validator';
import { Type } from 'class-transformer';

export class CreateBandaDto {
  @IsString()
  @IsNotEmpty()
  @MaxLength(150)
  nombre: string;

  @IsString()
  @IsNotEmpty()
  @MaxLength(100)
  pais: string;

  @IsNumber()
  @Type(() => Number)
  @Min(1800)
  @Max(2100)
  anioFormacion: number;

  @IsNumber()
  @Type(() => Number)
  generoId: number;
}

import { PartialType } from '@nestjs/mapped-types';
import { CreateBandaDto } from './create-banda.dto';

export class UpdateBandaDto extends PartialType(CreateBandaDto) {}

import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Banda } from './entities/banda.entity';
import { CreateBandaDto } from './dto/create-banda.dto';
import { UpdateBandaDto } from './dto/update-banda.dto';
import { Genero } from '../generos/entities/genero.entity';

@Injectable()
export class BandasService {
  constructor(
    @InjectRepository(Banda)
    private readonly bandasRepository: Repository<Banda>,
    @InjectRepository(Genero)
    private readonly generosRepository: Repository<Genero>,
  ) {}

  async create(dto: CreateBandaDto): Promise<Banda> {
    const genero = await this.generosRepository.findOne({ where: { id: dto.generoId } });
    if (!genero) {
      throw new BadRequestException(`Género con id ${dto.generoId} no existe`);
    }
    const banda = this.bandasRepository.create(dto);
    return this.bandasRepository.save(banda);
  }

  async findAll(): Promise<Banda[]> {
    return this.bandasRepository.find({ relations: ['genero'] });
  }

  async findOne(id: number): Promise<Banda> {
    const banda = await this.bandasRepository.findOne({
      where: { id },
      relations: ['genero'],
    });
    if (!banda) {
      throw new NotFoundException(`Banda con id ${id} no encontrada`);
    }
    return banda;
  }

  async update(id: number, dto: UpdateBandaDto): Promise<Banda> {
    if (dto.generoId) {
      const genero = await this.generosRepository.findOne({ where: { id: dto.generoId } });
      if (!genero) {
        throw new BadRequestException(`Género con id ${dto.generoId} no existe`);
      }
    }
    await this.findOne(id);
    await this.bandasRepository.update(id, dto);
    return this.findOne(id);
  }

  async remove(id: number): Promise<void> {
    const banda = await this.findOne(id);
    await this.bandasRepository.remove(banda);
  }
}

import { Controller, Get, Post, Put, Delete, Param, Body, ParseIntPipe, HttpCode, HttpStatus } from '@nestjs/common';
import { BandasService } from './bandas.service';
import { CreateBandaDto } from './dto/create-banda.dto';
import { UpdateBandaDto } from './dto/update-banda.dto';

@Controller('bandas')
export class BandasController {
  constructor(private readonly bandasService: BandasService) {}

  @Post()
  create(@Body() dto: CreateBandaDto) {
    return this.bandasService.create(dto);
  }

  @Get()
  findAll() {
    return this.bandasService.findAll();
  }

  @Get(':id')
  findOne(@Param('id', ParseIntPipe) id: number) {
    return this.bandasService.findOne(id);
  }

  @Put(':id')
  update(@Param('id', ParseIntPipe) id: number, @Body() dto: UpdateBandaDto) {
    return this.bandasService.update(id, dto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  remove(@Param('id', ParseIntPipe) id: number) {
    return this.bandasService.remove(id);
  }
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { BandasController } from './bandas.controller';
import { BandasService } from './bandas.service';
import { Banda } from './entities/banda.entity';

@Module({
  imports: [TypeOrmModule.forFeature([Banda])],
  controllers: [BandasController],
  providers: [BandasService],
  exports: [BandasService],
})
export class BandasModule {}

